import React, { useState } from 'react';

function obtenerEmbed(url) {
  if (!url) return '';
  const m = url.match(/(?:v=|\/embed\/|\.be\/)([A-Za-z0-9_-]{11})/);
  return m ? `https://www.youtube.com/embed/${m[1]}` : '';
}

export default function Experiencia() {
  const [url, setUrl] = useState('');
  const [embed, setEmbed] = useState('');

  const cargar = () => {
    const e = obtenerEmbed(url);
    setEmbed(e);
  };

  return (
    <section>
      <h2>Experiencia Personal</h2>
      <p style={{marginTop:8}}>Pega la URL de tu video de YouTube (máx 5 minutos). Asegúrate de aparecer en una esquina del video.</p>
      <div style={{display:'flex',gap:8,alignItems:'center',marginTop:12}}>
        <input style={{flex:1}} value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://www.youtube.com/watch?v=..." />
        <button onClick={cargar}>Cargar</button>
      </div>
      {embed ? (
        <div style={{marginTop:12}}>
          <div style={{position:'relative',paddingTop:'56.25%'}}>
            <iframe title="Experiencia" src={embed} style={{position:'absolute',left:0,top:0,width:'100%',height:'100%'}} frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen></iframe>
          </div>
        </div>
      ) : null}
    </section>
  );
}
